PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL := FALSE;
    ValveOut : BOOL := FALSE;
END_VAR

VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := TRUE, PT := T#5s);

IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

IF Level >= HighLimit AND NOT SafetyTimer.Q THEN
    SafetyTimer(IN := TRUE);
END_IF;

PumpIn := PumpIn AND NOT SafetyTimer.Q;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
END_VAR

// Safety condition: PumpIn must never run while the level is at or above the high limit (90%)
IF Level >= 90 THEN
    PumpIn := FALSE;
ELSIF Level <= 10 THEN
    PumpIn := TRUE;
ELSE
    PumpIn := FALSE;
END_IF;

// Control the outlet valve with hysteresis
IF Level >= 90 THEN
    ValveOut := TRUE;
ELSIF Level <= 10 THEN
    ValveOut := FALSE;
ELSE
    ValveOut := FALSE;
END_IF;

END_PROGRAM

