PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL := FALSE;
    DoorB : BOOL := FALSE;
END_VAR

VAR
    PrevOpenA_Cmd : BOOL := FALSE;
    PrevOpenB_Cmd : BOOL := FALSE;
    TimerA : TON;
    TimerB : TON;
END_VAR

PrevOpenA_Cmd := OpenA_Cmd;
PrevOpenB_Cmd := OpenB_Cmd;

IF NOT (OpenA_Cmd OR OpenB_Cmd) THEN
    DoorA := FALSE;
    DoorB := FALSE;
ELSIF OpenA_Cmd AND NOT OpenB_Cmd THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

TimerA(IN := OpenA_Cmd, PT := T#1s);
TimerB(IN := OpenB_Cmd, PT := T#1s);

DoorA := TimerA.Q;
DoorB := TimerB.Q;

END_PROGRAM

