IF DoorB_Req THEN
    DoorB := TRUE;
    DoorBTimer(IN := TRUE, PT := T#1s);
ELSE
    DoorB := FALSE;
    DoorBTimer(IN := FALSE);
END_IF;

IF DoorA AND DoorB THEN
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

