PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    ConveyorRunning : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT (GuardClosed OR Fault), PT := T#1s);

IF StartPB AND GuardClosed AND NOT Fault AND NOT ConveyorRunning THEN
    ConveyorRunning := TRUE;
ELSIF StopPB OR NOT GuardClosed OR Fault THEN
    ConveyorRunning := FALSE;
END_IF;

Conveyor := ConveyorRunning AND NOT SafetyTimer.Q;
END_PROGRAM

