PROGRAM intersection
VAR
    State : INT := 0;
    T_NS_green : TON;
    T_NS_yellow : TON;
    T_NS_allred : TON;
    T_EW_green : TON;
    T_EW_yellow : TON;
    T_EW_allred : TON;
END_VAR

CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE; EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_EW_green(IN := TRUE, PT := T#2s);
        IF T_EW_green.Q THEN
            State := 1;
        END_IF;

    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE; EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_EW_green(IN := FALSE);
        T_EW_yellow(IN := TRUE, PT := T#1s);
        IF T_EW_yellow.Q THEN
            State := 2;
        END_IF;

    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE; EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_EW_yellow(IN := FALSE);
        T_EW_allred(IN := TRUE, PT := T#1s);
        IF T_EW_allred.Q THEN
            State := 3;
        END_IF;

    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE; EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        T_EW_allred(IN := FALSE);
        T_NS_green(IN := TRUE, PT := T#2s);
        IF T_NS_green.Q THEN
            State := 4;
        END_IF;

    4:
        NS_G := FALSE; NS_Y := TRUE; NS_R := TRUE; EW_G := FALSE; EW_Y := FALSE; EW_R := FALSE;
        T_NS_green(IN := FALSE);
        T_NS_yellow(IN := TRUE, PT := T#1s);
        IF T_NS_yellow.Q THEN
            State := 5;
        END_IF;

    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE; EW_G := FALSE; EW_Y := FALSE; EW_R := FALSE;
        T_NS_yellow(IN := FALSE);
        T_NS_allred(IN := TRUE, PT := T#1s);
        IF T_NS_allred.Q THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    T_NS_G, T_NS_Y, T_EW_G, T_EW_Y, T_AllRed : TON;
END_VAR

T_NS_G(IN := (State = 0 OR State = 3), PT := T#2s);
T_NS_Y(IN := (State = 1 OR State = 4), PT := T#1s);
T_EW_G(IN := (State = 3 OR State = 0), PT := T#2s);
T_EW_Y(IN := (State = 4 OR State = 1), PT := T#1s);
T_AllRed(IN := (State = 2 OR State = 5), PT := T#1s);

NS_G := T_NS_G.Q AND NOT (T_EW_G.Q OR T_EW_Y.Q);
NS_Y := T_NS_Y.Q AND NOT (T_EW_G.Q OR T_EW_Y.Q);
NS_R := NOT (T_NS_G.Q OR T_NS_Y.Q) AND (State <> 2);

EW_G := T_EW_G.Q AND NOT (T_NS_G.Q OR T_NS_Y.Q);
EW_Y := T_EW_Y.Q AND NOT (T_NS_G.Q OR T_NS_Y.Q);
EW_R := NOT (T_EW_G.Q OR T_EW_Y.Q) AND (State <> 5);

CASE State OF
    0, 3: 
        IF T_NS_G.Q THEN
            State := State + 1;
        END_IF;
    1, 4: 
        IF T_NS_Y.Q THEN
            State := State + 1;
        END_IF;
    2: 
        IF T_AllRed.Q THEN
            State := 0;
        END_IF;
    ELSE
        State := 0;
END_CASE;
END_PROGRAM

