    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
