    HeatTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: -- Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: -- Heat
        IF NOT FillValve THEN
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;
        IF Temp >= TEMP_SET THEN
            HeatTimer(IN := TRUE, PT := PT_REACT);
            IF HeatTimer.Q THEN
                State := 3;
            END_IF;
        ELSE
            HeatTimer(IN := FALSE);
        END_IF;

    3: -- React
        IF Not HeatTimer.Q THEN
            Heater := TRUE;
