                ELSE
                    State := 3;
                    T_ReactTimer(IN := TRUE, PT := T#5s);
                END_IF;
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
