            StarTimer(IN := TRUE, PT := PT_STAR);
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
