        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := T_C3.Q;
        IF T_C3.Q THEN
            State := 2;
        END_IF;

    2:
        C1 := FALSE;
        C2 := T_C2.Q;
        C3 := T_C3.Q;
        IF T_C2.Q AND T_C3.Q THEN
            State := 3;
        END_IF;

    3:
        C1 := T_C2.Q;
        C2 := T_C3.Q;
        C3 := T_C3.Q;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF NOT EStop OR StopPB THEN
    State := 0;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    SeqTimer_C3 : TON;
    SeqTimer_C2 : TON;
END_VAR

SeqTimer_C3.TP := T#2s;
SeqTimer_C2.TP := T#2s;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF SeqTimer_C3.Q AND NOT EStop THEN
            State := 2;
        END_IF;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF SeqTimer_C2.Q AND NOT EStop THEN
            State := 3;
        END_IF;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    ELSE:
        State := 0;
END_CASE;

SeqTimer_C3(IN := NOT EStop);
SeqTimer_C2(IN := NOT EStop);

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
END_VAR

VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR

PrevTrigger := Trigger;

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSIF NOT PrevTrigger AND Trigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
    IF Count = 3 THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

